// Package airports holds the embedded table of every airport with an IATA
// code, generated by cmd/gen-airports into table_gen.go. It is a stand-alone
// package to avoid a store ↔ providers import cycle.
package airports

import (
	"fmt"
	"strings"
)

type Entry struct {
	Lat, Lon float64
	Name     string
	// TZ is the IANA timezone string at the airport (e.g. "Europe/London",
	// "America/New_York"). Used to render scheduled times in the airport's
	// local time on the client.
	TZ string
	// City is the city the airport serves (e.g. "London", "New York"). Used to
	// give imported trips a place-based name instead of the first flight's
	// ident. Several airports serving the same city share a City value.
	City string
}

// Lookup returns lat/lon for a 3-letter IATA code, or zeros + false.
// Case-insensitive.
func Lookup(code string) (lat, lon float64, ok bool) {
	a, ok := table[strings.ToUpper(strings.TrimSpace(code))]
	if !ok {
		return 0, 0, false
	}
	return a.Lat, a.Lon, true
}

// LookupTZ returns the IANA timezone for a 3-letter IATA code, or "" + false.
// Case-insensitive.
func LookupTZ(code string) (string, bool) {
	a, ok := table[strings.ToUpper(strings.TrimSpace(code))]
	if !ok || a.TZ == "" {
		return "", false
	}
	return a.TZ, true
}

// LookupCity returns the city served by a 3-letter IATA code, or "" + false.
// Case-insensitive.
func LookupCity(code string) (string, bool) {
	a, ok := table[strings.ToUpper(strings.TrimSpace(code))]
	if !ok || a.City == "" {
		return "", false
	}
	return a.City, true
}

// Label renders a human-friendly airport label "Name (CODE)" for an IATA code,
// e.g. "London Heathrow (LHR)". The name is the embedded table's airport name
// when the code is on-table; otherwise the supplied providerName (the flight
// data source's airport name) is used. When no name is available it falls back to the bare
// upper-cased code ("NQY"), so the result is never blank for a non-empty code.
// A blank code yields "".
func Label(code, providerName string) string {
	code = strings.ToUpper(strings.TrimSpace(code))
	if code == "" {
		return ""
	}
	name := ""
	if a, ok := table[code]; ok && a.Name != "" {
		name = a.Name
	} else if p := strings.TrimSpace(providerName); p != "" {
		name = p
	}
	if name == "" {
		return code
	}
	return fmt.Sprintf("%s (%s)", name, code)
}

// CodeIn returns the known IATA code a free-text label names, or "". A
// three-letter all-caps token counts only when the label is clearly about an
// airport: it is the bare code ("LHR"), the code is in brackets ("Sal (SID)"),
// the label says "airport" or "terminal", or it carries a terminal number
// ("LHR T5"). Real codes spell ordinary words (THE, INN, BUS, VAN), so a token
// alone is not enough: "Hotel near LHR" names no airport.
func CodeIn(label string) string {
	label = strings.TrimSpace(label)
	toks := strings.FieldsFunc(label, func(r rune) bool {
		return !(r >= 'A' && r <= 'Z') && !(r >= 'a' && r <= 'z') && !(r >= '0' && r <= '9')
	})
	l := strings.ToLower(label)
	airporty := strings.Contains(l, "airport") || strings.Contains(l, "terminal")
	for _, tok := range toks {
		if isTerminalNumber(tok) {
			airporty = true
		}
	}
	for _, tok := range toks {
		if len(tok) != 3 || tok != strings.ToUpper(tok) || strings.ContainsAny(tok, "0123456789") {
			continue
		}
		if _, ok := table[tok]; !ok {
			continue
		}
		if airporty || label == tok || strings.Contains(label, "("+tok+")") {
			return tok
		}
	}
	return ""
}

// isTerminalNumber reports whether a token is a terminal number such as "T5"
// or "T12".
func isTerminalNumber(tok string) bool {
	if len(tok) < 2 || len(tok) > 3 || tok[0] != 'T' {
		return false
	}
	for _, r := range tok[1:] {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}
